"""Tiny deterministic legal loopback HTTP fixture for isolated aria2 smoke tests.

This serves synthetic generated bytes only. It never contacts the internet and
cannot be used to fetch real media or other external resources.
"""
from http.server import BaseHTTPRequestHandler, HTTPServer

PAYLOAD = b"MooBee Fetch legal synthetic test payload\n" * 1024


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path != "/fixture.bin":
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header("Content-Type", "application/octet-stream")
        self.send_header("Content-Length", str(len(PAYLOAD)))
        self.end_headers()
        self.wfile.write(PAYLOAD)

    def log_message(self, *args):
        return


if __name__ == "__main__":
    print("Fixture on loopback only", flush=True)
    HTTPServer(("127.0.0.1", 8111), Handler).serve_forever()
